function closestPointOnLineFromRay(
  rOrig: Vec3,
  rDir: Vec3,
  lOrig: Vec3,
  lDir: Vec3
): number {
  const w0 = vec3(rOrig[0] - lOrig[0], rOrig[1] - lOrig[1], rOrig[2] - lOrig[2]);
  const a = dot(rDir, rDir);
  const b = dot(rDir, lDir);
  const c = dot(lDir, lDir);
  const d = dot(rDir, w0);
  const e = dot(lDir, w0);

  const denom = a * c - b * b;
  if (denom < 1e-9) {
    return e / c;
  }
  return (a * e - b * d) / denom;
}

